/** AUTO-GENERATED short SFX clips (base64 audio/mp4) derived from the pet videos. */
// Wire playback in PetWidget on the action buttons.
export type SfxName = 'voice' | 'avatar' | 'perform0' | 'perform1' | 'perform2' | 'perform3'
const LIB: Record<string, Partial<Record<SfxName, string>>> = {
  'whale': {
    'voice': 'data:audio/mp4;base64,',
    'avatar': 'data:audio/mp4;base64,',
    'perform0': 'data:audio/mp4;base64,',
    'perform1': 'data:audio/mp4;base64,',
    'perform2': 'data:audio/mp4;base64,',
    'perform3': 'data:audio/mp4;base64,'
  },
  'robot': {
    'voice': 'data:audio/mp4;base64,',
    'avatar': 'data:audio/mp4;base64,',
    'perform0': 'data:audio/mp4;base64,',
    'perform1': 'data:audio/mp4;base64,',
    'perform2': 'data:audio/mp4;base64,',
    'perform3': 'data:audio/mp4;base64,'
  },
  'silver-moon': {
    'voice': 'data:audio/mp4;base64,',
    'avatar': 'data:audio/mp4;base64,',
    'perform0': 'data:audio/mp4;base64,',
    'perform1': 'data:audio/mp4;base64,',
    'perform2': 'data:audio/mp4;base64,',
    'perform3': 'data:audio/mp4;base64,'
  },
}

/** Two ping-pong players so consecutive clips crossfade instead of hard-cutting. */
let players: HTMLAudioElement[] | null = null
let active = 0

/** Clamp a value into the media element's legal volume range. */
function clamp01(value: number): number {
  return value < 0 ? 0 : value > 1 ? 1 : value
}

/** Per-element ramp token, so a stale ramp cannot fight a newer one. */
const rampToken = new WeakMap<HTMLAudioElement, number>()

/** Ramp an element volume to `to` over `ms` ms (smooth fade in/out). */
function ramp(el: HTMLAudioElement, to: number, ms: number): void {
  const target = clamp01(to)
  const token = (rampToken.get(el) ?? 0) + 1
  rampToken.set(el, token)
  const from = clamp01(el.volume)
  const t0 = performance.now()
  const step = (now: number): void => {
    if (rampToken.get(el) !== token) return
    // The rAF timestamp is the frame's start and can precede `t0`, so the
    // progress must be clamped at both ends or the volume goes negative.
    const p = clamp01((now - t0) / ms)
    try {
      el.volume = clamp01(from + (target - from) * p)
    } catch {
      return
    }
    if (p < 1) requestAnimationFrame(step)
  }
  requestAnimationFrame(step)
}

/** Play a short SFX clip for an avatar + cue, crossfading from the previous one. */
export function playSfx(avatar: string, name: SfxName): void {
  const url = LIB[avatar]?.[name]
  if (url === undefined) return
  try {
    if (players === null) players = [new Audio(), new Audio()]
    const a = players[active]!
    const other = players[1 - active]!
    // Fade the previous clip out while the new one fades in -> smooth seam.
    if (!other.paused && other.src !== "") ramp(other, 0, 140)
    a.src = url
    a.currentTime = 0
    a.volume = 0
    void a.play().then(() => {
      ramp(a, 0.7, 180)
      window.setTimeout(() => { if (!other.paused) other.pause() }, 240)
    }).catch(() => {})
    active = 1 - active
  } catch { /* audio unavailable; ignore */ }
}
